<script setup lang="ts">import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'; import * as echarts from 'echarts'; import type { TemperaturePoint } from '@/types/domain'; const props = defineProps<{ points: TemperaturePoint[] }>(); const element = ref<HTMLElement>(); let chart: echarts.ECharts | undefined; function render() { if (!element.value) return; chart ??= echarts.init(element.value); chart.setOption({ grid: { left: 38, right: 20, top: 20, bottom: 28 }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: props.points.map((point) => point.stageName || point.time || '') }, yAxis: { type: 'value', name: '°C' }, series: [{ type: 'line', smooth: true, data: props.points.map((point) => point.temperature), itemStyle: { color: '#118b82' }, areaStyle: { color: 'rgba(32,167,154,.12)' } }] }); } onMounted(() => nextTick(render)); watch(() => props.points, render, { deep: true }); onBeforeUnmount(() => chart?.dispose())</script>
<template><div ref="element" class="temperature-chart"></div></template>
